import { useCallback, useEffect, useRef, useState } from 'react';
import { Activity, AlertTriangle, ArrowLeft, BarChart3, BookOpen, Camera, Check, ChevronRight, CircleUserRound, Cloud, CloudOff, Database, Eye, EyeOff, FileImage, GitCompareArrows, History, Home, ImagePlus, Info, Leaf, Link2, LockKeyhole, LogOut, Mail, Menu, RefreshCw, ScanLine, Search, Settings, ShieldCheck, Trash2, Upload, Users, X } from 'lucide-react';
import { analyzeLeaf } from './services/inferenceService';
import { api, authenticate, getToken, logout, setToken } from './services/api';

const THRESHOLD = Number(import.meta.env.VITE_CONFIDENCE_THRESHOLD ?? 70);
const FARMER_NAV = [['/farmer/dashboard', 'Home', Home], ['/farmer/scan', 'Scan', ScanLine], ['/farmer/history', 'History', History], ['/farmer/diseases', 'Guide', BookOpen], ['/farmer/profile', 'Profile', CircleUserRound]];
const ADMIN_NAV = [['/admin/dashboard', 'Dashboard', Home], ['/admin/farmers', 'Farmers', Users], ['/admin/experts', 'Agricultural Reviewers', ShieldCheck], ['/admin/diagnoses', 'Diagnoses', ScanLine], ['/admin/diseases', 'Disease Knowledge', BookOpen], ['/admin/sources', 'Research Sources', Link2], ['/admin/analytics', 'Analytics', BarChart3], ['/admin/model-comparison', 'Model Comparison', GitCompareArrows], ['/admin/system', 'Model Information', Settings], ['/admin/profile', 'Profile', CircleUserRound]];
const EXPERT_NAV = [['/expert/dashboard', 'Home', Home], ['/expert/cases', 'Review Queue', ScanLine], ['/expert/reviewed', 'Reviewed Cases', History], ['/expert/diseases', 'Disease Knowledge', BookOpen], ['/expert/sources', 'Research Sources', Link2], ['/expert/dataset', 'Dataset Candidates', Database], ['/expert/profile', 'Profile', CircleUserRound]];
const formatDate = (value, time = false) => value ? new Intl.DateTimeFormat('en-PH', { month: 'short', day: 'numeric', year: 'numeric', ...(time ? { hour: 'numeric', minute: '2-digit' } : {}) }).format(new Date(value)) : 'Not available';
const titleCase = (value = '') => value.replaceAll('-', ' ').replace(/\b\w/g, (letter) => letter.toUpperCase());
const confidenceText = (value) => value < THRESHOLD ? 'Uncertain result' : value >= 85 ? 'High confidence' : 'Moderate confidence';
const mapDiagnosis = (item) => ({ id: String(item.id), diseaseId: item.disease?.slug || item.predicted_class, predictedClass: item.predicted_class, disease: item.disease, confidence: Number(item.confidence), date: item.diagnosed_at, source: item.source, synced: item.sync_status === 'synced' || item.source === 'web', isSimulated: Boolean(item.is_simulated), image: item.image_url, gradcam: item.gradcam_url, farmerNotes: item.farmer_notes || '', priority: Number(item.review_priority || 0), reviewReasons: item.review_reasons || [], latency: item.inference_time_ms || 0, model: item.model_version || 'Not specified', user: item.user, review: item.review || null });
const roleHome = (role) => role === 'admin' ? '/admin/dashboard' : role === 'agricultural_expert' ? '/expert/dashboard' : '/farmer/dashboard';

function IconButton({ label, children, ...props }) { return <button className="icon-button" aria-label={label} title={label} {...props}>{children}</button>; }
function LogoMark({ inverse = false }) { return <img className="logo-mark" src={inverse ? '/assets/brand/dahonmd-logo-white.png' : '/assets/brand/dahonmd-logo-green.png'} alt="" aria-hidden="true" />; }
function Loading({ text = 'Loading...' }) { return <div className="role-loading"><RefreshCw className="spin" size={24} /><p>{text}</p></div>; }
function Empty({ icon: Icon = Leaf, title, text, action, actionLabel }) { return <div className="empty-state role-empty"><Icon size={30} /><h3>{title}</h3><p>{text}</p>{action && <button className="primary-button" onClick={action}>{actionLabel}</button>}</div>; }
function ReviewRequestForm({ initialNotes = '', onSubmit }) { const [notes, setNotes] = useState(initialNotes); return <div className="review-request-form"><label>Notes for the agricultural reviewer<textarea value={notes} maxLength={1000} onChange={(event) => setNotes(event.target.value)} placeholder="Optional: describe changes, repeated symptoms, or field conditions." /></label><button className="secondary-button full" onClick={() => onSubmit(notes)}><ShieldCheck size={17} />Request Agricultural Review</button></div>; }

function AuthPage({ mode, onAuthenticated, navigate }) {
  const signup = mode === 'register'; const [form, setForm] = useState({ name: '', email: '', password: '', password_confirmation: '' }); const [error, setError] = useState(''); const [errors, setErrors] = useState({}); const [busy, setBusy] = useState(false);
  const [showPassword, setShowPassword] = useState(false); const [remember, setRemember] = useState(true); const [notice, setNotice] = useState('');
  const submit = async (event) => { event.preventDefault(); setBusy(true); setError(''); setErrors({}); setNotice(''); try { const user = await authenticate(mode, form, remember); onAuthenticated(user); navigate(roleHome(user.role)); } catch (exception) { setError(exception.message); setErrors(exception.errors || {}); } finally { setBusy(false); } };
  const unavailable = (feature) => setNotice(`${feature} is not available yet.`);
  return <main className="auth-page"><section className="auth-card role-auth-card"><div className="auth-brand-lockup"><span><LogoMark /></span><strong>Dahon<span>MD</span></strong><small>Leaf health guide</small></div><div className="auth-welcome"><h1><Leaf size={22} fill="currentColor" />{signup ? 'Create your account' : 'Welcome back!'}</h1><p>{signup ? 'Save scans and access your leaf-health workspace.' : 'Sign in to continue checking the health of your banana plants.'}</p></div><form className="auth-form" onSubmit={submit}>{signup && <label>Full name<div className="auth-field"><CircleUserRound size={18} /><input autoComplete="name" placeholder="Your name" value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} required /></div>{errors.name && <small>{errors.name[0]}</small>}</label>}<label>Email address<div className="auth-field"><Mail size={18} /><input type="email" autoComplete="email" placeholder="you@example.com" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} required /></div>{errors.email && <small>{errors.email[0]}</small>}</label><label>Password<div className="auth-field"><LockKeyhole size={18} /><input type={showPassword ? 'text' : 'password'} autoComplete={signup ? 'new-password' : 'current-password'} placeholder="Enter your password" value={form.password} onChange={(event) => setForm({ ...form, password: event.target.value })} required /><button type="button" className="auth-eye" aria-label={showPassword ? 'Hide password' : 'Show password'} onClick={() => setShowPassword(!showPassword)}>{showPassword ? <EyeOff size={18} /> : <Eye size={18} />}</button></div>{errors.password && <small>{errors.password[0]}</small>}</label>{signup && <label>Confirm password<div className="auth-field"><LockKeyhole size={18} /><input type={showPassword ? 'text' : 'password'} autoComplete="new-password" placeholder="Repeat your password" value={form.password_confirmation} onChange={(event) => setForm({ ...form, password_confirmation: event.target.value })} required /></div></label>}<div className="auth-options"><label className="remember-control"><input type="checkbox" checked={remember} onChange={(event) => setRemember(event.target.checked)} /><span><Check size={12} /></span>Remember me</label>{!signup && <button type="button" onClick={() => unavailable('Password recovery')}>Forgot password?</button>}</div>{(error || notice) && <div className={error ? 'form-error' : 'auth-notice'} role="status">{error || notice}</div>}<button className="primary-button auth-submit" disabled={busy}>{busy ? <RefreshCw className="spin" size={17} /> : <Leaf size={18} fill="currentColor" />}{busy ? 'Please wait' : signup ? 'Create account' : 'Sign in'}</button></form><div className="auth-divider"><span>or</span></div><button className="auth-google" type="button" onClick={() => unavailable('Google sign-in')}><b>G</b>Continue with Google</button><p className="auth-switch">{signup ? 'Already have an account?' : 'New to DahonMD?'} <button onClick={() => navigate(signup ? '/login' : '/signup')}>{signup ? 'Sign in' : 'Create account'} <ChevronRight size={14} /></button></p></section></main>;
}

function Shell({ role, user, path, navigate, onSignedOut, children, online }) {
  const items = role === 'admin' ? ADMIN_NAV : role === 'agricultural_expert' ? EXPERT_NAV : FARMER_NAV;
  const currentSection = items.find(([route]) => route === path)?.[1] || 'Home';
  const [open, setOpen] = useState(false);
  const signOut = async () => { await logout(); onSignedOut(); };

  return <div className={`role-shell ${role}-shell`}>
    {open && <button className="role-scrim" aria-label="Close menu" onClick={() => setOpen(false)} />}
    <aside className={`role-sidebar ${open ? 'open' : ''}`}>
      <div className="role-brand">
        <span><LogoMark inverse /></span>
        <div><strong>DahonMD</strong><small>{role === 'admin' ? 'Admin workspace' : role === 'agricultural_expert' ? 'Agricultural review' : 'Leaf health guide'}</small></div>
        <IconButton label="Close menu" onClick={() => setOpen(false)}><X size={19} /></IconButton>
      </div>
      <nav>{items.filter(([route]) => !route.endsWith('/profile')).map(([route, label, Icon]) => <button key={route} className={path === route ? 'active' : ''} onClick={() => { navigate(route); setOpen(false); }}><Icon size={18} /><span>{label}</span></button>)}</nav>
      <div className="role-sidebar-spacer" />
      {role === 'farmer' && <div className={`sidebar-network ${online ? '' : 'offline'}`}>{online ? <Cloud size={16} /> : <CloudOff size={16} />}<span>{online ? 'Online' : 'Offline'}</span></div>}
      <div className="sidebar-footer">
        <button className="sidebar-account" onClick={() => navigate(role === 'admin' ? '/admin/profile' : role === 'agricultural_expert' ? '/expert/profile' : '/farmer/profile')}><span>{user.name.split(' ').map((part) => part[0]).join('').slice(0, 2)}</span><div><strong>{user.name}</strong><small>{role === 'admin' ? 'Administrator' : role === 'agricultural_expert' ? 'Agricultural Reviewer' : 'Farmer account'}</small></div></button>
        <button className="sidebar-logout" onClick={signOut}><LogOut size={17} />Log out</button>
      </div>
    </aside>
    <main className="role-main">
      <header className="role-topbar">
        <IconButton label="Open menu" onClick={() => setOpen(true)}><Menu size={21} /></IconButton>
        <div className="role-header-brand"><strong>{currentSection}</strong></div>
        {role === 'farmer' && <span className={`top-network ${online ? '' : 'offline'}`}>{online ? <Cloud size={15} /> : <CloudOff size={15} />}{online ? 'Online' : 'Offline'}</span>}
      </header>
      <div className="role-page">{children}</div>
    </main>
    {role === 'farmer' && <nav className="farmer-bottom-nav">{FARMER_NAV.map(([route, label, Icon]) => <button key={route} className={path === route ? 'active' : ''} onClick={() => navigate(route)}><Icon size={20} /><span>{label}</span></button>)}</nav>}
  </div>;
}

function RecentCard({ record, onOpen }) {
  const name = record.disease?.name || (record.diseaseId === 'development-unconfigured' ? 'Development result' : titleCase(record.diseaseId)); return <button className="recent-scan-card" onClick={() => onOpen(record)}><span className="recent-thumb">{record.image ? <img src={record.image} alt="Saved banana leaf" /> : <Leaf size={24} />}</span><span className="recent-copy"><strong>{record.confidence < THRESHOLD ? 'Uncertain result' : record.diseaseId === 'healthy' ? 'No supported pattern detected' : name}</strong><small>{confidenceText(record.confidence)} · {record.confidence.toFixed(1)}%</small><small>{formatDate(record.date, true)}</small></span><span className="recent-status">{record.synced ? <><Cloud size={15} />Saved online</> : <><CloudOff size={15} />Waiting to sync</>}</span><ChevronRight size={18} /></button>;
}

function FarmerHome({ user, records, online, navigate, onOpen }) {
  return <div className="role-stack"><section className="farmer-welcome"><h1>Hello, {user.name.split(' ')[0]}.</h1><p>Check a banana leaf for visible signs of supported diseases.</p></section><section className="farmer-home-grid"><button className="farmer-scan-hero" onClick={() => navigate('/farmer/scan')}><span className="scan-hero-icon"><Camera size={38} /></span><span><strong>Scan a leaf</strong><p>Take or upload a clear photo to check its visible patterns.</p></span><ChevronRight size={26} /></button><div className="panel quick-help"><h2>Before you scan</h2><button onClick={() => navigate('/farmer/scan')}><Camera size={19} /><span><strong>Take a clear photo</strong><small>Use one leaf, good light, and clear focus.</small></span><ChevronRight size={18} /></button><button onClick={() => navigate('/farmer/diseases')}><BookOpen size={19} /><span><strong>Explore the disease guide</strong><small>Read verified information for supported diseases.</small></span><ChevronRight size={18} /></button><button onClick={() => navigate('/farmer/history')}><History size={19} /><span><strong>Review past results</strong><small>Open saved scans and guidance.</small></span><ChevronRight size={18} /></button></div></section><section className="panel farmer-recent"><div className="panel-heading"><h2>Recent scans</h2><button className="text-button" onClick={() => navigate('/farmer/history')}>View all<ChevronRight size={17} /></button></div>{records.slice(0, 4).map((record) => <RecentCard key={record.id} record={record} onOpen={onOpen} />)}{!records.length && <Empty title="No scans yet" text="Scan your first leaf to start your history." action={() => navigate('/farmer/scan')} actionLabel="Scan a leaf" />}</section>{!online && <section className="farmer-sync-banner offline"><CloudOff size={22} /><div><strong>You're offline</strong><p>You can scan a leaf now, then connect to save the result.</p></div></section>}</div>;
}

function Tips() { return <div className="scan-tip-card"><strong>Photo tips</strong><ul><li><Check size={16} />Show one leaf in bright, even light.</li><li><Check size={16} />Keep the affected area centered and in focus.</li><li><Check size={16} />Avoid blur, shadows, and distant shots.</li></ul><small>A clearer photo can improve image quality, but it cannot guarantee an accurate diagnosis.</small></div>; }

function FarmerScan({ onSaved, navigate, online }) {
  const input = useRef(null); const [image, setImage] = useState(null); const [imageFile, setImageFile] = useState(null); const [fileName, setFileName] = useState(''); const [stage, setStage] = useState('choose'); const [result, setResult] = useState(null); const [error, setError] = useState('');
  const useFile = (file) => { if (!file?.type.startsWith('image/')) { setError("We couldn't use this photo. Please choose another image."); return; } if (image?.startsWith('blob:')) URL.revokeObjectURL(image); setImage(URL.createObjectURL(file)); setImageFile(file); setFileName(file.name); setStage('preview'); setError(''); };
  const reset = () => { if (image?.startsWith('blob:')) URL.revokeObjectURL(image); setImage(null); setImageFile(null); setFileName(''); setResult(null); setStage('choose'); setError(''); };
  const check = async () => { setStage('checking'); try { setResult(await analyzeLeaf(image)); setStage('result'); } catch { setError('Something went wrong. Please try again.'); setStage('preview'); } };
  const save = async (requestReview = false, farmerNotes = '') => { if (!online) { setError('Connect to the internet before saving this result online.'); return; } try { await onSaved({ diseaseId: result.diseaseId, confidence: result.confidence, latency: result.latency, date: new Date().toISOString(), source: 'web', model: result.model, image: image === '/assets/black-sigatoka-sample.png' ? image : null, farmerNotes }, imageFile, requestReview); navigate('/farmer/history'); } catch { setError('Something went wrong. Please try again.'); } };
  if (stage === 'result') return <FarmerResult image={image} result={result} onReset={reset} onSave={save} error={error} />;
  return <div className="role-stack"><Heading title="Scan a leaf" text="Choose a clear photo and review it before analysis." /><section className="farmer-scan-layout"><div className="panel scan-photo-panel">{!image ? <div className="friendly-drop" onDrop={(event) => { event.preventDefault(); useFile(event.dataTransfer.files[0]); }} onDragOver={(event) => event.preventDefault()}><span><ImagePlus size={35} /></span><h2>Choose a photo</h2><p>JPG, PNG, or WEBP</p><button className="primary-button" onClick={() => input.current?.click()}><Upload size={18} />Choose from device</button><button className="sample-link" onClick={() => { setImage('/assets/black-sigatoka-sample.png'); setFileName('Development sample'); setStage('preview'); }}>Use development sample</button><input ref={input} hidden type="file" accept="image/*" onChange={(event) => useFile(event.target.files[0])} /></div> : <div className="friendly-preview"><img src={image} alt="Selected banana leaf" />{stage === 'checking' && <div className="checking-cover"><RefreshCw className="spin" size={28} /><strong>Checking the leaf...</strong><p>Examining visible patterns.</p></div>}<span><FileImage size={16} />{fileName}</span></div>}</div><aside className="panel scan-check-panel"><span className="step-number">{image ? '2' : '1'}</span><h2>{image ? 'Review your photo' : 'Take a clear photo'}</h2><p>{image ? 'Make sure the leaf is centered and easy to see.' : 'Use these tips for a clearer result.'}</p><Tips /><div className="development-note"><Info size={18} /><p>This development build uses simulated results and cannot confirm disease.</p></div>{image && <><button className="primary-button full" disabled={stage === 'checking'} onClick={check}><ScanLine size={18} />Analyze photo</button><button className="secondary-button full" disabled={stage === 'checking'} onClick={reset}>Choose another</button></>}</aside></section>{error && <div className="form-error">{error}</div>}</div>;
}

function FarmerResult({ image, result, onReset, onSave, error }) {
  const uncertain = result.confidence < THRESHOLD; const healthy = result.diseaseId === 'healthy'; const [disease, setDisease] = useState(null); const [farmerNotes, setFarmerNotes] = useState('');
  useEffect(() => { api('/diseases').then((payload) => setDisease(payload.data.find((item) => item.slug === result.diseaseId) || null)).catch(() => undefined); }, [result.diseaseId]);
  const hasVerifiedGuidance = !uncertain && disease?.is_verified;
  return <div className="role-stack"><section className="result-title"><button className="text-button" onClick={onReset}><ArrowLeft size={18} />Scan another leaf</button><p className="eyebrow">RESULT</p><h1>{uncertain ? "We couldn't identify this leaf confidently." : healthy ? 'No supported disease pattern was strongly detected' : 'Possible Disease'}</h1></section><section className="plain-result-grid"><div className="panel plain-result-image"><img src={image} alt="Scanned banana leaf" /></div><div className={`panel plain-result-summary ${uncertain ? 'uncertain' : healthy ? 'healthy' : ''}`}>{!uncertain && <><span className="section-label">{healthy ? 'SCREENING RESULT' : 'POSSIBLE DISEASE'}</span><h2>{disease?.name || 'Supported class'}</h2></>}<div className="confidence-plain"><strong>{confidenceText(result.confidence)}</strong><span>{result.confidence.toFixed(1)}%</span></div><p>{uncertain ? 'The system could not make a confident match. Try another clear photo or save it for an agricultural reviewer. No disease-specific management is shown for an uncertain result.' : 'The image matched visual patterns learned for this supported class. Model confidence is not the probability that the plant truly has the disease.'}</p>{uncertain && <div className="retry-box"><strong>Try again with:</strong><ul><li>Better lighting</li><li>One leaf centered</li><li>The affected area visible</li><li>Less blur</li></ul><button className="primary-button" onClick={onReset}>Take Another Photo</button><label className="farmer-review-notes">What have you noticed?<textarea value={farmerNotes} onChange={(event) => setFarmerNotes(event.target.value)} placeholder="Optional: describe changes, spread, weather, or repeated symptoms." maxLength={1000} /></label><button className="secondary-button full" onClick={() => onSave(true, farmerNotes)}><ShieldCheck size={17} />Save &amp; Request Agricultural Review</button></div>}</div></section>{hasVerifiedGuidance && <section className="result-guidance"><article className="panel"><span className="section-label">WHAT THIS MEANS</span><p>{healthy ? 'No supported disease pattern was strongly detected in this image. The model covers only its trained classes, so continue monitoring the plant.' : disease.description}</p><span className="section-label">WHAT YOU MAY NOTICE</span>{disease.symptoms?.length ? <ul>{disease.symptoms.map((symptom) => <li key={symptom}><Check size={17} />{symptom}</li>)}</ul> : <p>Insufficient verified evidence available.</p>}</article><article className="panel result-action"><ShieldCheck size={24} /><div><span className="section-label">WHAT YOU CAN DO</span><p>{disease.management || 'Insufficient verified evidence available.'}</p><span className="section-label">WHEN TO ASK FOR HELP</span><p>{disease.professional_referral || 'Ask a qualified agriculture professional if symptoms are severe, unusual, spreading rapidly, or uncertain.'}</p></div></article></section>}<details className="panel attention-panel"><summary><Eye size={18} />Areas the system noticed</summary><div><figure><img src={image} alt="Original leaf" /><figcaption>Original leaf</figcaption></figure><figure className="highlighted"><img src={image} alt="Illustrative highlighted preview" /><i /><figcaption>Development visualization</figcaption></figure></div><p>Highlighted areas contributed more strongly to the simulated result. They do not prove that a pathogen is present.</p></details><Warning />{error && <div className="form-error">{error}</div>}<div className="result-actions-bottom"><button className="secondary-button" onClick={onReset}>Scan Another Leaf</button><button className="primary-button" onClick={() => onSave(false)}>Save Result</button></div></div>;
}

function Warning() { return <section className="screening-warning"><Info size={20} /><p>This result is a screening aid based on the supported image classes. Some plant diseases and nutrient or environmental problems can look similar. Seek confirmation from a qualified agriculture or plant-health professional when symptoms are severe, unusual, spreading rapidly, or the result is uncertain.</p></section>; }
function Heading({ title, text }) { return <section className="role-page-heading"><h1>{title}</h1>{text && <p>{text}</p>}</section>; }

function FarmerHistory({ records, navigate, onOpen }) {
  const [query, setQuery] = useState(''); const [kind, setKind] = useState('all'); const [date, setDate] = useState(''); const filtered = records.filter((record) => { const healthy = record.diseaseId === 'healthy'; return (kind === 'all' || (kind === 'healthy' ? healthy : !healthy)) && (!date || record.date?.slice(0, 10) === date) && `${record.disease?.name || record.diseaseId} ${record.id}`.toLowerCase().includes(query.toLowerCase()); });
  return <div className="role-stack"><Heading title="Scan history" text="Your newest saved results appear first." /><section className="panel history-role-panel"><div className="friendly-filters"><label><Search size={18} /><input placeholder="Search scans" value={query} onChange={(event) => setQuery(event.target.value)} /></label><select aria-label="Filter by result" value={kind} onChange={(event) => setKind(event.target.value)}><option value="all">All results</option><option value="healthy">Healthy</option><option value="disease">Possible disease</option></select><input aria-label="Filter by date" type="date" value={date} onChange={(event) => setDate(event.target.value)} /></div>{filtered.map((record) => <RecentCard key={record.id} record={record} onOpen={onOpen} />)}{!filtered.length && <Empty icon={History} title={records.length ? 'No matching scans' : 'No scans yet'} text={records.length ? 'Adjust your filters and try again.' : 'Scan your first leaf to start your history.'} action={!records.length ? () => navigate('/farmer/scan') : undefined} actionLabel="Scan a leaf" />}</section></div>;
}

function DiseaseGuide() {
  const [items, setItems] = useState([]); const [selected, setSelected] = useState(null); const [loading, setLoading] = useState(true); useEffect(() => { api('/diseases').then((payload) => { setItems(payload.data); setSelected(payload.data[0] || null); }).catch(() => setItems([])).finally(() => setLoading(false)); }, []); if (loading) return <Loading text="Loading disease guide..." />;
  return <div className="role-stack"><Heading eyebrow="GUIDE" title="Banana Leaf Disease Guide" text="Only source-verified records appear here." />{!items.length ? <Empty icon={BookOpen} title="DISEASE CONTENT PENDING" text="A validated trained-model label map is not yet available. Disease-specific guidance will remain unavailable until the model artifact and sources are verified." /> : <section className="guide-role-layout"><div className="guide-role-list">{items.map((item) => <button className={selected?.id === item.id ? 'active' : ''} key={item.id} onClick={() => setSelected(item)}>{item.image_url ? <img src={item.image_url} alt="" /> : <span><Leaf size={23} /></span>}<div><strong>{item.name}</strong><small>{item.short_description || item.description}</small></div><ChevronRight size={18} /></button>)}</div>{selected && <article className="panel guide-role-detail">{selected.image_url && <img className="guide-main-image" src={selected.image_url} alt={`Verified representative image for ${selected.name}`} />}<span className="section-label">VERIFIED DISEASE GUIDE</span><h2>{selected.name}</h2>{selected.scientific_name && <p className="scientific-name">{selected.scientific_name}</p>}<section><h3>What it looks like</h3><p>{selected.description}</p><ul>{selected.symptoms?.map((symptom) => <li key={symptom}><Check size={16} />{symptom}</li>)}</ul></section><section><h3>What causes it</h3><p>{selected.causal_agent || 'Insufficient verified evidence available.'}</p></section><section><h3>What you can do</h3><p>{selected.management || 'Insufficient verified evidence available.'}</p></section><section><h3>How to help prevent spread</h3><p>{selected.prevention || 'Insufficient verified evidence available.'}</p></section><section><h3>When to seek expert help</h3><p>{selected.professional_referral || 'Ask a qualified agriculture professional when symptoms are severe, unusual, spreading rapidly, or uncertain.'}</p></section><section><h3>Image-only limitations</h3><p>{selected.image_only_limitations || 'A leaf image cannot provide laboratory confirmation.'}</p></section><Warning /></article>}</section>}</div>;
}

function DiagnosisDialog({ record, onClose, onRequestReview }) { if (!record) return null; const reviewed = record.review && record.review.review_status !== 'pending'; return <><button className="dialog-scrim" aria-label="Close result" onClick={onClose} /><aside className="diagnosis-dialog"><header><div><span className="section-label">SAVED RESULT</span><h2>{record.confidence < THRESHOLD ? 'Uncertain result' : record.disease?.name || titleCase(record.diseaseId)}</h2></div><IconButton label="Close result" onClick={onClose}><X size={20} /></IconButton></header>{record.image ? <img className="dialog-image" src={record.image} alt="Saved banana leaf" /> : <div className="dialog-image placeholder"><Leaf size={45} /></div>}<div className="confidence-plain"><strong>{confidenceText(record.confidence)}</strong><span>{record.confidence.toFixed(1)}%</span></div><dl><div><dt>Date</dt><dd>{formatDate(record.date, true)}</dd></div><div><dt>Source</dt><dd>{titleCase(record.source)}</dd></div><div><dt>Save status</dt><dd>{record.synced ? 'Saved online' : 'Waiting to sync'}</dd></div>{record.farmerNotes && <div><dt>Your notes</dt><dd>{record.farmerNotes}</dd></div>}</dl>{record.review?.review_status === 'pending' && <section className="review-notice"><ShieldCheck size={20} /><div><strong>Review requested</strong><p>An agricultural reviewer can assess this saved image.</p></div></section>}{reviewed && <section className="review-result"><span className="section-label">AGRICULTURAL REVIEW AVAILABLE</span><h3>{titleCase(record.review.review_status.replaceAll('_', '-'))}</h3><p><strong>AI screening:</strong> {titleCase(record.predictedClass)} ({record.confidence.toFixed(1)}%)</p>{record.review.verified_label && <p><strong>Reviewer assessment:</strong> {titleCase(record.review.verified_label)}</p>}<p><strong>Recommended follow-up:</strong> {record.review.farmer_follow_up}</p>{record.review.next_steps?.length > 0 && <p><strong>Next steps:</strong> {record.review.next_steps.map((step) => titleCase(step.replaceAll('_', '-'))).join(' · ')}</p>}</section>}{!record.review && <ReviewRequestForm initialNotes={record.farmerNotes} onSubmit={(notes) => onRequestReview(record, notes)} />}<Warning /></aside></>; }

function ProfilePage({ user, onUser, onSignedOut }) {
  const [profile, setProfile] = useState({ name: user.name, email: user.email }); const [passwords, setPasswords] = useState({ current_password: '', password: '', password_confirmation: '' }); const [message, setMessage] = useState(''); const [error, setError] = useState('');
  const save = async (event) => { event.preventDefault(); try { const payload = await api('/profile', { method: 'PUT', body: JSON.stringify(profile) }); onUser(payload.data.user); setMessage('Profile updated.'); } catch (exception) { setError(exception.message); } }; const change = async (event) => { event.preventDefault(); try { await api('/profile/password', { method: 'PUT', body: JSON.stringify(passwords) }); setPasswords({ current_password: '', password: '', password_confirmation: '' }); setMessage('Password updated.'); } catch (exception) { setError(exception.message); } }; const remove = async () => { if (!confirm('Permanently delete your account and diagnosis records?')) return; await api('/profile', { method: 'DELETE' }); setToken(null); onSignedOut(); };
  return <div className="role-stack"><Heading eyebrow="ACCOUNT" title="Profile" text="Keep your account information simple and up to date." /><section className="profile-role-grid"><form className="panel role-form" onSubmit={save}><h2>Edit Profile</h2><label>Name<input value={profile.name} onChange={(event) => setProfile({ ...profile, name: event.target.value })} required /></label><label>Email<input type="email" value={profile.email} onChange={(event) => setProfile({ ...profile, email: event.target.value })} required /></label><button className="primary-button">Save Profile</button></form><form className="panel role-form" onSubmit={change}><h2>Change Password</h2><label>Current password<input type="password" value={passwords.current_password} onChange={(event) => setPasswords({ ...passwords, current_password: event.target.value })} required /></label><label>New password<input type="password" value={passwords.password} onChange={(event) => setPasswords({ ...passwords, password: event.target.value })} required /></label><label>Confirm new password<input type="password" value={passwords.password_confirmation} onChange={(event) => setPasswords({ ...passwords, password_confirmation: event.target.value })} required /></label><button className="secondary-button">Update Password</button><button type="button" className="danger-button" onClick={remove}>Delete Account</button></form></section>{message && <div className="success-message">{message}</div>}{error && <div className="form-error">{error}</div>}</div>;
}

function Stat({ label, value, note, icon: Icon }) { return <article className="admin-stat-card"><span><Icon size={21} /></span><div><small>{label}</small><strong>{value}</strong><p>{note}</p></div></article>; }
function useAdmin(path) { const [data, setData] = useState(null); const [error, setError] = useState(''); useEffect(() => { api(path).then((payload) => setData(payload.data)).catch((exception) => setError(exception.message)); }, [path]); return { data, error }; }
function Distribution({ title, values, extra }) { return <article className="panel admin-distribution"><h2>{title}</h2>{Object.entries(values).map(([label, value]) => <div key={label}><span>{titleCase(label)}</span><strong>{value}</strong></div>)}{!Object.keys(values).length && <p className="empty-copy">No diagnoses yet.</p>}{extra && <div><span>{extra[0]}</span><strong>{extra[1]}</strong></div>}</article>; }
function DiagnosisRows({ items }) { return items.length ? items.map((item) => <div className="admin-record-row" key={item.id}>{item.image_url ? <img src={item.image_url} alt="" /> : <span className="record-placeholder"><Leaf size={20} /></span>}<div><strong>{item.disease?.name || titleCase(item.predicted_class)}</strong><small>{item.user?.name || 'Unknown farmer'}</small></div><span>{item.confidence}%</span><span>{titleCase(item.source)}</span><time>{formatDate(item.diagnosed_at, true)}</time></div>) : <Empty icon={ScanLine} title="No diagnoses yet." text="New saved scans will appear here." />; }

function AdminDashboard() {
  const { data, error } = useAdmin('/admin/dashboard'); if (error) return <div className="form-error">{error}</div>; if (!data) return <Loading text="Loading dashboard..." />;
  return <div className="role-stack"><Heading eyebrow="ADMIN DASHBOARD" title="System Overview" text="Every value below comes from the current database." /><section className="admin-stat-grid"><Stat label="Total Farmers" value={data.total_farmers} note="Farmer accounts" icon={Users} /><Stat label="Total Diagnoses" value={data.total_diagnoses} note="Mobile and web" icon={Database} /><Stat label="Scans Today" value={data.diagnoses_today} note="Current database date" icon={Activity} /><Stat label="Average Model Confidence" value={`${Number(data.average_confidence).toFixed(1)}%`} note="Not biological probability" icon={BarChart3} /><Stat label="Uncertain Results" value={data.uncertain_predictions} note={`${Number(data.uncertain_prediction_rate).toFixed(1)}% of records`} icon={AlertTriangle} /><Stat label="Pending / Failed Syncs" value={data.pending_or_failed_syncs} note="Database sync state" icon={CloudOff} /></section><section className="admin-overview-grid"><Distribution title="Diagnosis Distribution" values={data.diagnoses_per_class} /><Distribution title="Healthy versus Diseased" values={{ healthy: data.healthy_predictions, diseased: data.diseased_predictions }} /><Distribution title="Source Distribution" values={data.diagnoses_per_source} extra={['Simulated records', data.simulated_predictions]} /></section><section className="panel admin-list-panel"><span className="section-label">LATEST ACTIVITY</span><h2>Recent Diagnoses</h2><DiagnosisRows items={data.recent_diagnoses} /></section></div>;
}

function AdminAnalytics() {
  const { data, error } = useAdmin('/admin/analytics'); if (error) return <div className="form-error">{error}</div>; if (!data) return <Loading text="Loading analytics..." />; const timeline = Object.entries(data.diagnoses_over_time); const max = Math.max(1, ...timeline.map(([, total]) => Number(total))); const review = data.model_review_analytics;
  return <div className="role-stack"><Heading eyebrow="ANALYTICS" title="Diagnosis Activity" text="Useful research summaries without fabricated performance values." /><section className="admin-stat-grid three"><Stat label="Diagnoses" value={data.total_diagnoses} note="Saved records" icon={Database} /><Stat label="Average Confidence" value={`${Number(data.average_confidence).toFixed(1)}%`} note="Model confidence, not diagnostic certainty" icon={Activity} /><Stat label="Uncertain" value={data.uncertain_predictions} note={`${Number(data.uncertain_prediction_rate).toFixed(1)}% below ${data.confidence_threshold}%`} icon={AlertTriangle} /></section><section className="admin-overview-grid"><article className="panel analytics-chart"><h2>Diagnoses Over Time</h2>{timeline.length ? <div className="timeline-bars">{timeline.map(([date, total]) => <div key={date}><span style={{ height: `${Math.max(8, (Number(total) / max) * 100)}%` }}><b>{total}</b></span><small>{new Date(`${date}T00:00:00`).toLocaleDateString('en-PH', { month: 'short', day: 'numeric' })}</small></div>)}</div> : <p className="empty-copy">No diagnosis activity yet.</p>}</article><Distribution title="Mobile versus Web" values={data.diagnoses_per_source} /><Distribution title="Healthy versus Diseased" values={{ healthy: data.healthy_predictions, diseased: data.diseased_predictions }} /></section><Heading eyebrow="MODEL REVIEW ANALYTICS" title="AI–Reviewer Agreement" text="Structured agricultural reviews provide agreement evidence without being presented as laboratory accuracy." /><section className="admin-stat-grid"><Stat label="Reviewed Diagnoses" value={review.reviewed_diagnoses} note={`${review.comparable_reviews} comparable assessments`} icon={ShieldCheck} /><Stat label="AI–Reviewer Agreement" value={review.agreement_rate === null ? 'Not available' : `${Number(review.agreement_rate).toFixed(1)}%`} note="Agreement, not diagnostic accuracy" icon={Check} /><Stat label="Disagreements" value={review.disagreements} note="Different supported class" icon={AlertTriangle} /><Stat label="Disagreement Confidence" value={review.average_disagreement_confidence === null ? "Not available" : `${Number(review.average_disagreement_confidence).toFixed(1)}%`} note="Average model confidence in disagreements" icon={Activity} /><Stat label="Outside Supported Classes" value={review.possible_outside_supported_classes} note="Reviewer flagged" icon={Info} /><Stat label="Unable to Determine" value={review.unable_to_determine} note={`${review.field_inspection_required} require field inspection`} icon={Eye} /></section><section className="admin-overview-grid"><Distribution title="Most Confused Classes" values={review.most_confused_classes} /><Distribution title="Disagreements by AI Class" values={review.disagreements_by_predicted_class} /><article className="panel review-band-panel"><h2>Agreement by Confidence Band</h2>{Object.entries(review.agreement_by_confidence).map(([band, item]) => <div key={band}><span>{titleCase(band)} confidence</span><strong>{item.agreement_rate === null ? 'No comparable reviews' : `${Number(item.agreement_rate).toFixed(1)}% agreement`}</strong><small>{item.reviewed} reviewed</small></div>)}</article><Distribution title="Research Dataset Candidates" values={data.dataset_candidates} /></section><div className="development-note"><Info size={18} /><p>{review.reference_standard_note}</p></div></div>;
}

function FarmersAdmin() {
  const empty = { name: '', email: '', password: '', password_confirmation: '' }; const [items, setItems] = useState([]); const [search, setSearch] = useState(''); const [editing, setEditing] = useState(null); const [form, setForm] = useState(empty); const [error, setError] = useState('');
  const load = useCallback(() => api(`/admin/farmers?per_page=50${search ? `&search=${encodeURIComponent(search)}` : ''}`).then((payload) => setItems(payload.data.items)).catch((exception) => setError(exception.message)), [search]); useEffect(() => { load(); }, [load]);
  const edit = (item) => { setEditing(item.id); setForm({ name: item.name, email: item.email, password: '', password_confirmation: '' }); }; const submit = async (event) => { event.preventDefault(); const data = { ...form }; if (editing && !data.password) { delete data.password; delete data.password_confirmation; } try { await api(`/admin/farmers${editing ? `/${editing}` : ''}`, { method: editing ? 'PUT' : 'POST', body: JSON.stringify(data) }); setForm(empty); setEditing(null); setError(''); load(); } catch (exception) { setError(exception.message); } }; const remove = async (item) => { if (!confirm(`Delete farmer ${item.name} and their diagnosis records?`)) return; await api(`/admin/farmers/${item.id}`, { method: 'DELETE' }); load(); };
  return <div className="role-stack"><Heading eyebrow="ADMINISTRATION" title="Farmers" text="Create, search, and maintain farmer accounts." /><form className="admin-search" onSubmit={(event) => { event.preventDefault(); load(); }}><Search size={18} /><input placeholder="Search farmer name or email" value={search} onChange={(event) => setSearch(event.target.value)} /><button className="secondary-button">Search</button></form><form className="panel admin-editor" onSubmit={submit}><h2>{editing ? 'Update Farmer' : 'Create Farmer Account'}</h2><div><label>Name<input value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} required /></label><label>Email<input type="email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} required /></label><label>Password<input type="password" value={form.password} onChange={(event) => setForm({ ...form, password: event.target.value })} required={!editing} /></label><label>Confirm password<input type="password" value={form.password_confirmation} onChange={(event) => setForm({ ...form, password_confirmation: event.target.value })} required={!editing} /></label></div><footer><button className="primary-button">{editing ? 'Save Changes' : 'Create Farmer'}</button>{editing && <button type="button" className="secondary-button" onClick={() => { setEditing(null); setForm(empty); }}>Cancel</button>}</footer></form>{error && <div className="form-error">{error}</div>}<section className="panel admin-table-role"><header><span>Farmer</span><span>Joined</span><span>Diagnoses</span><span>Recent Activity</span><span>Actions</span></header>{items.map((item) => <div key={item.id}><span><strong>{item.name}</strong><small>{item.email}</small></span><span>{formatDate(item.created_at)}</span><span>{item.diagnoses_count ?? 0}</span><span>{formatDate(item.last_activity_at, true)}</span><span><button onClick={() => edit(item)}>Edit</button><button className="danger-link" onClick={() => remove(item)}>Delete</button></span></div>)}{!items.length && <Empty icon={Users} title="No farmers found." text="Try another search or create a farmer account." />}</section></div>;
}

function ExpertsAdmin() {
  const empty = { name: '', email: '', password: '', password_confirmation: '', role: 'agricultural_expert' }; const [items, setItems] = useState([]); const [search, setSearch] = useState(''); const [editing, setEditing] = useState(null); const [form, setForm] = useState(empty); const [error, setError] = useState('');
  const load = useCallback(() => api(`/admin/experts?per_page=50${search ? `&search=${encodeURIComponent(search)}` : ''}`).then((payload) => setItems(payload.data.items)).catch((exception) => setError(exception.message)), [search]); useEffect(() => { load(); }, [load]);
  const edit = (item) => { setEditing(item.id); setForm({ ...empty, name: item.name, email: item.email }); }; const submit = async (event) => { event.preventDefault(); const data = { ...form }; if (editing && !data.password) { delete data.password; delete data.password_confirmation; } try { await api(`/admin/experts${editing ? `/${editing}` : ''}`, { method: editing ? 'PUT' : 'POST', body: JSON.stringify(data) }); setForm(empty); setEditing(null); setError(''); load(); } catch (exception) { setError(exception.message); } }; const remove = async (item) => { if (!confirm(`Delete agricultural reviewer ${item.name}? Completed reviews will remain as an audit record without an assigned account.`)) return; await api(`/admin/experts/${item.id}`, { method: 'DELETE' }); load(); };
  return <div className="role-stack"><Heading eyebrow="ADMINISTRATION" title="Agricultural Reviewers" text="Only designate qualified plant-health reviewers. This role cannot access system administration." /><form className="admin-search" onSubmit={(event) => { event.preventDefault(); load(); }}><Search size={18} /><input placeholder="Search reviewer name or email" value={search} onChange={(event) => setSearch(event.target.value)} /><button className="secondary-button">Search</button></form><form className="panel admin-editor" onSubmit={submit}><h2>{editing ? 'Update Agricultural Reviewer' : 'Create Agricultural Reviewer'}</h2><div><label>Name<input value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} required /></label><label>Email<input type="email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} required /></label><label>Password<input type="password" value={form.password} onChange={(event) => setForm({ ...form, password: event.target.value })} required={!editing} /></label><label>Confirm password<input type="password" value={form.password_confirmation} onChange={(event) => setForm({ ...form, password_confirmation: event.target.value })} required={!editing} /></label></div><footer><button className="primary-button">{editing ? 'Save Changes' : 'Create Reviewer'}</button>{editing && <button type="button" className="secondary-button" onClick={() => { setEditing(null); setForm(empty); }}>Cancel</button>}</footer></form>{error && <div className="form-error">{error}</div>}<section className="panel admin-table-role"><header><span>Reviewer</span><span>Joined</span><span>Reviews</span><span>Recent Activity</span><span>Actions</span></header>{items.map((item) => <div key={item.id}><span><strong>{item.name}</strong><small>{item.email}</small></span><span>{formatDate(item.created_at)}</span><span>Qualified role</span><span>{formatDate(item.last_activity_at, true)}</span><span><button onClick={() => edit(item)}>Edit</button><button className="danger-link" onClick={() => remove(item)}>Delete</button></span></div>)}{!items.length && <Empty icon={ShieldCheck} title="No agricultural reviewers found." text="Create an account only after confirming the reviewer's qualifications." />}</section></div>;
}

function DiagnosesAdmin() {
  const [items, setItems] = useState([]); const [filters, setFilters] = useState({ class: '', source: '', date_from: '', date_to: '', confidence_min: '', confidence_max: '' }); const [error, setError] = useState('');
  const load = useCallback(() => { const query = new URLSearchParams(Object.entries(filters).filter(([, value]) => value)); query.set('per_page', '50'); api(`/admin/diagnoses?${query}`).then((payload) => setItems(payload.data.items)).catch((exception) => setError(exception.message)); }, [filters]); useEffect(() => { load(); }, [load]); const remove = async (item) => { if (!confirm('Delete this diagnosis record?')) return; await api(`/admin/diagnoses/${item.id}`, { method: 'DELETE' }); load(); };
  return <div className="role-stack"><Heading eyebrow="ADMINISTRATION" title="Diagnoses" text="Review original predictions. Predictions cannot be silently edited." /><section className="panel diagnosis-filters"><label>Class<input placeholder="Class slug" value={filters.class} onChange={(event) => setFilters({ ...filters, class: event.target.value })} /></label><label>Source<select value={filters.source} onChange={(event) => setFilters({ ...filters, source: event.target.value })}><option value="">All</option><option value="mobile">Mobile</option><option value="web">Web</option></select></label><label>From<input type="date" value={filters.date_from} onChange={(event) => setFilters({ ...filters, date_from: event.target.value })} /></label><label>To<input type="date" value={filters.date_to} onChange={(event) => setFilters({ ...filters, date_to: event.target.value })} /></label><label>Minimum confidence<input type="number" min="0" max="100" value={filters.confidence_min} onChange={(event) => setFilters({ ...filters, confidence_min: event.target.value })} /></label><label>Maximum confidence<input type="number" min="0" max="100" value={filters.confidence_max} onChange={(event) => setFilters({ ...filters, confidence_max: event.target.value })} /></label></section>{error && <div className="form-error">{error}</div>}<section className="panel admin-table-role diagnoses"><header><span>Image / Result</span><span>Farmer</span><span>Confidence</span><span>Source / Sync</span><span>Date</span><span>Actions</span></header>{items.map((item) => <div key={item.id}><span className="diagnosis-admin-name">{item.image_url ? <img src={item.image_url} alt="" /> : <i><Leaf size={18} /></i>}<strong>{item.disease?.name || titleCase(item.predicted_class)}</strong></span><span>{item.user?.name || 'Unknown farmer'}</span><span>{item.confidence}%</span><span>{titleCase(item.source)} · {item.sync_status || (item.source === 'web' ? 'saved' : 'unknown')}</span><span>{formatDate(item.diagnosed_at, true)}</span><span><button className="danger-link" onClick={() => remove(item)}>Delete</button></span></div>)}{!items.length && <Empty icon={ScanLine} title="No diagnosis records match these filters." text="Change the filters or wait for new scans." />}</section></div>;
}

function DiseasesAdmin() {
  const empty = { slug: '', model_class_key: '', name: '', alternative_names: [], scientific_name: '', causal_agent: '', pathogen_type: '', short_description: '', farmer_summary: '', curative_status: 'unclear_evidence', evidence_level: 'limited', image_only_limitations: '', professional_referral: '', prevention: '' };
  const [items, setItems] = useState([]); const [classes, setClasses] = useState([]); const [contentStatus, setContentStatus] = useState(''); const [form, setForm] = useState(empty); const [editing, setEditing] = useState(null); const [selected, setSelected] = useState(null); const [error, setError] = useState('');
  const load = useCallback(async () => { try { const [knowledge, system] = await Promise.all([api('/admin/diseases'), api('/admin/system')]); setItems(knowledge.data); setClasses(system.data.classes); setContentStatus(system.data.disease_content_status); } catch (exception) { setError(exception.message); } }, []); useEffect(() => { load(); }, [load]);
  const edit = (item) => { setEditing(item.id); setForm({ ...empty, ...item, alternative_names: item.alternative_names || [] }); };
  const submit = async (event) => { event.preventDefault(); try { await api(`/admin/diseases${editing ? `/${editing}` : ''}`, { method: editing ? 'PUT' : 'POST', body: JSON.stringify(form) }); setForm(empty); setEditing(null); setError(''); load(); } catch (exception) { setError(exception.message); } };
  const setStatus = async (item, status) => { try { await api(`/admin/diseases/${item.id}/status`, { method: 'PUT', body: JSON.stringify({ status }) }); setError(''); load(); } catch (exception) { setError(exception.message); } };
  const inspect = async (item) => { try { const payload = await api(`/admin/diseases/${item.id}`); setSelected(payload.data); } catch (exception) { setError(exception.message); } };
  return <div className="role-stack"><Heading eyebrow="ADMIN / RESEARCH" title="Disease Knowledge" text="Draft and manage content, then submit researched records to an agricultural reviewer for verification." /><div className={`development-note ${classes.length === 5 ? '' : 'warning'}`}><Info size={18} /><p>{contentStatus || 'Checking the final label map...'}</p></div>{classes.length === 5 && <form className="panel admin-editor disease-editor" onSubmit={submit}><h2>{editing ? 'Edit content (requires re-review)' : 'Create draft from model label'}</h2><div><label>Model class key<select value={form.model_class_key} onChange={(event) => setForm({ ...form, model_class_key: event.target.value, slug: event.target.value })} required><option value="">Select validated class</option>{classes.map((label) => <option key={label}>{label}</option>)}</select></label><label>Accepted disease name<input value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} required /></label><label>Scientific name<input value={form.scientific_name || ''} onChange={(event) => setForm({ ...form, scientific_name: event.target.value })} /></label><label>Causal agent<input value={form.causal_agent || ''} onChange={(event) => setForm({ ...form, causal_agent: event.target.value })} /></label><label>Pathogen type<select value={form.pathogen_type || ''} onChange={(event) => setForm({ ...form, pathogen_type: event.target.value })}><option value="">Not established</option>{['fungus', 'bacterium', 'virus', 'other'].map((value) => <option key={value}>{value}</option>)}</select></label><label>Curative status<select value={form.curative_status} onChange={(event) => setForm({ ...form, curative_status: event.target.value })}>{['unclear_evidence', 'manageable_not_curable', 'no_known_cure', 'curative_treatment_available'].map((value) => <option key={value}>{titleCase(value.replaceAll('_', '-'))}</option>)}</select></label><label>Evidence level<select value={form.evidence_level} onChange={(event) => setForm({ ...form, evidence_level: event.target.value })}>{['limited', 'moderate', 'high'].map((value) => <option key={value}>{titleCase(value)}</option>)}</select></label>{[['short_description','Short description'],['farmer_summary','Farmer summary'],['prevention','How to help prevent spread'],['professional_referral','When to seek expert help'],['image_only_limitations','Image-only limitations']].map(([field,label]) => <label key={field}>{label}<textarea value={form[field] || ''} onChange={(event) => setForm({ ...form, [field]: event.target.value })} /></label>)}</div><footer><button className="primary-button">{editing ? 'Save and return for review' : 'Create Draft'}</button>{editing && <button type="button" className="secondary-button" onClick={() => { setEditing(null); setForm(empty); }}>Cancel</button>}</footer></form>}{error && <div className="form-error">{error}</div>}<section className="panel admin-table-role knowledge-table"><header><span>Disease</span><span>Pathogen</span><span>Status</span><span>Evidence</span><span>Sources</span><span>Last reviewed</span><span>Actions</span></header>{items.map((item) => <div key={item.id}><span><strong>{item.name}</strong><small>{item.model_class_key}</small></span><span>{item.causal_agent || 'Pending'}</span><span><b className={`status-pill ${item.verification_status}`}>{item.verification_status}</b></span><span>{item.evidence_level}</span><span>{item.sources_count ?? 0}</span><span>{formatDate(item.last_reviewed_at)}</span><span><button onClick={() => inspect(item)}>Review</button><button onClick={() => edit(item)}>Edit</button>{item.verification_status === 'draft' && <button onClick={() => setStatus(item, 'researched')}>Submit for Review</button>}<button className="danger-link" onClick={() => setStatus(item, 'archived')}>Archive</button></span></div>)}{!items.length && <Empty icon={BookOpen} title="DISEASE CONTENT PENDING" text="No final model label map is available, so no disease records have been populated." />}</section>{selected && <section className="admin-overview-grid"><article className="panel"><span className="section-label">FARMER CONTENT</span><h2>{selected.disease.name}</h2><p>{selected.disease.description || 'Insufficient verified evidence available.'}</p><h3>Management and Prevention</h3><p>{selected.disease.management || 'Insufficient verified evidence available.'}</p><h3>Image-only limitations</h3><p>{selected.disease.image_only_limitations || 'Not yet documented.'}</p></article><article className="panel"><span className="section-label">RESEARCH EVIDENCE</span><h2>{selected.disease.scientific_name || 'Scientific name pending'}</h2><p><strong>Causal agent:</strong> {selected.disease.causal_agent || 'Pending'}</p><p><strong>Evidence:</strong> {selected.disease.evidence_level}</p><p><strong>Sources:</strong> {selected.disease.sources_count ?? 0}</p>{selected.regulatory_recheck_required && <div className="form-error">REGULATORY RE-CHECK REQUIRED</div>}<button className="secondary-button" onClick={() => setSelected(null)}>Close detail</button></article></section>}</div>;
}

function ResearchSourcesAdmin() {
  const empty = { title: '', authors: '', year: '', journal_or_institution: '', source_type: 'peer_reviewed_article', doi: '', reference_url: '', country_or_region: '', peer_reviewed: true, philippines_specific: false, notes: '' };
  const [items, setItems] = useState([]); const [form, setForm] = useState(empty); const [editing, setEditing] = useState(null); const [filters, setFilters] = useState({ search: '', peer_reviewed: false, philippines_specific: false, institution: '', disease_id: '' }); const [error, setError] = useState('');
  const load = useCallback(() => { const query = new URLSearchParams(Object.entries(filters).filter(([, value]) => value)); api(`/admin/research-sources?${query}`).then((payload) => setItems(payload.data)).catch((exception) => setError(exception.message)); }, [filters]); useEffect(() => { load(); }, [load]);
  const submit = async (event) => { event.preventDefault(); const body = { ...form, year: form.year ? Number(form.year) : null, doi: form.doi || null, reference_url: form.reference_url || null }; try { await api(`/admin/research-sources${editing ? `/${editing}` : ''}`, { method: editing ? 'PUT' : 'POST', body: JSON.stringify(body) }); setEditing(null); setForm(empty); setError(''); load(); } catch (exception) { setError(exception.message); } };
  const edit = (item) => { setEditing(item.id); setForm({ ...empty, ...item, year: item.year || '' }); };
  return <div className="role-stack"><Heading eyebrow="ADMIN / RESEARCH" title="Research Sources" text="Maintain traceable peer-reviewed, authoritative, Philippine, and regulatory evidence." /><section className="panel diagnosis-filters"><label>Search<input value={filters.search} onChange={(event) => setFilters({ ...filters, search: event.target.value })} /></label><label>Institution<input value={filters.institution} onChange={(event) => setFilters({ ...filters, institution: event.target.value })} /></label><label>Disease record ID<input type="number" min="1" value={filters.disease_id} onChange={(event) => setFilters({ ...filters, disease_id: event.target.value })} /></label><label className="check-filter"><input type="checkbox" checked={filters.peer_reviewed} onChange={(event) => setFilters({ ...filters, peer_reviewed: event.target.checked })} /> Peer reviewed</label><label className="check-filter"><input type="checkbox" checked={filters.philippines_specific} onChange={(event) => setFilters({ ...filters, philippines_specific: event.target.checked })} /> Philippines-specific</label></section><form className="panel admin-editor source-editor" onSubmit={submit}><h2>{editing ? 'Update source' : 'Add source'}</h2><div>{[['title','Title'],['authors','Authors'],['year','Publication year'],['journal_or_institution','Journal or institution'],['doi','DOI (leave blank if none)'],['reference_url','Reference URL'],['country_or_region','Country or region']].map(([field,label]) => <label key={field}>{label}<input type={field === 'year' ? 'number' : field === 'reference_url' ? 'url' : 'text'} value={form[field] || ''} onChange={(event) => setForm({ ...form, [field]: event.target.value })} required={['title','authors','journal_or_institution'].includes(field)} /></label>)}<label>Source type<select value={form.source_type} onChange={(event) => setForm({ ...form, source_type: event.target.value })}>{['peer_reviewed_article','systematic_review','review_article','government_guideline','FAO_guideline','university_extension','regulatory_document','academic_book_chapter','research_institute'].map((value) => <option key={value} value={value}>{titleCase(value.replaceAll('_','-'))}</option>)}</select></label><label>Notes<textarea value={form.notes || ''} onChange={(event) => setForm({ ...form, notes: event.target.value })} /></label><label className="check-filter"><input type="checkbox" checked={form.peer_reviewed} onChange={(event) => setForm({ ...form, peer_reviewed: event.target.checked })} /> Peer reviewed</label><label className="check-filter"><input type="checkbox" checked={form.philippines_specific} onChange={(event) => setForm({ ...form, philippines_specific: event.target.checked })} /> Philippines-specific</label></div><footer><button className="primary-button">{editing ? 'Save and trigger re-review' : 'Add Source'}</button>{editing && <button type="button" className="secondary-button" onClick={() => { setEditing(null); setForm(empty); }}>Cancel</button>}</footer></form>{error && <div className="form-error">{error}</div>}<section className="panel admin-table-role source-table"><header><span>Reference</span><span>Year</span><span>Type</span><span>Quality</span><span>Claims</span><span>Actions</span></header>{items.map((item) => <div key={item.id}><span><strong>{item.authors} ({item.year || 'n.d.'}). {item.title}.</strong><small>{item.journal_or_institution}{item.doi ? ` · DOI: ${item.doi}` : ''}</small></span><span>{item.year || 'n.d.'}</span><span>{titleCase(item.source_type.replaceAll('_','-'))}</span><span>{item.peer_reviewed ? 'Peer reviewed' : 'Authoritative'}{item.philippines_specific ? ' · Philippines' : ''}</span><span>{item.evidence_count}</span><span><button onClick={() => edit(item)}>Edit</button>{item.reference_url && <a href={item.reference_url} target="_blank" rel="noreferrer">Open</a>}</span></div>)}{!items.length && <Empty icon={Link2} title="No research sources yet." text="Add only sources that have been checked against the original publication or authority." />}</section></div>;
}

function EvidenceAudit() {
  const { data, error } = useAdmin('/admin/research-sources');
  if (error) return <div className="form-error">{error}</div>;
  if (!data) return <Loading text="Loading claim mappings..." />;
  const claims = data.flatMap((source) => (source.evidence || []).map((evidence) => ({ ...evidence, source })));
  return <section className="panel evidence-audit"><span className="section-label">CLAIM-LEVEL TRACEABILITY</span><h2>Claims using each source</h2>{claims.map((claim) => <article key={claim.id}><strong>{titleCase(claim.claim_type.replaceAll('_', '-'))} · {titleCase(claim.evidence_strength)}</strong><p>{claim.claim_text}</p><small>{claim.disease?.name || 'Disease record'} — {claim.source.authors} ({claim.source.year || 'n.d.'}). {claim.source.title}.{claim.source.doi ? ` DOI: ${claim.source.doi}` : ''}</small></article>)}{!claims.length && <p className="empty-copy">No sources have been mapped to disease claims yet.</p>}</section>;
}

function ExpertDashboard({ navigate }) {
  const { data, error } = useAdmin('/expert/dashboard'); if (error) return <div className="form-error">{error}</div>; if (!data) return <Loading text="Loading review dashboard..." />;
  return <div className="role-stack"><Heading eyebrow="AGRICULTURAL REVIEWER" title="Review Dashboard" text="Assess uncertain saved images and validate researched disease information without changing original model outputs." /><section className="admin-stat-grid"><Stat label="Needs Review" value={data.needs_review} note="Open image cases" icon={ShieldCheck} /><Stat label="Uncertain AI Results" value={data.uncertain_results} note="Below confidence threshold" icon={AlertTriangle} /><Stat label="Farmer Review Requests" value={data.farmer_review_requests} note="Explicitly requested" icon={Users} /><Stat label="Content Awaiting Verification" value={data.disease_content_awaiting_verification} note="Researched records" icon={BookOpen} /></section><section className="panel expert-case-list"><div className="panel-heading"><div><span className="section-label">CASES NEEDING REVIEW</span><h2>Newest open cases</h2></div><button className="text-button" onClick={() => navigate('/expert/cases')}>View all<ChevronRight size={17} /></button></div>{data.cases.map((item) => <button key={item.id} className="expert-case-row" onClick={() => navigate(`/expert/cases?case=${item.id}`)}>{item.image_url ? <img src={item.image_url} alt="Banana leaf submitted for review" /> : <span><Leaf size={23} /></span>}<div><strong>{item.disease?.name || titleCase(item.predicted_class)}</strong><small>Farmer: {item.user?.name || 'Unknown'} · {formatDate(item.diagnosed_at, true)}</small></div><b>{Number(item.confidence).toFixed(1)}%</b><em>{item.review_reasons?.join(' · ') || (item.review?.review_status === 'pending' ? 'Farmer requested review' : 'Low confidence')}</em><ChevronRight size={18} /></button>)}{!data.cases.length && <Empty icon={Check} title="No cases need review." text="New uncertain results and farmer requests will appear here." />}</section></div>;
}

function ExpertCases({ reviewed = false }) {
  const [items, setItems] = useState([]); const [classes, setClasses] = useState([]); const [selected, setSelected] = useState(null); const [form, setForm] = useState({ review_status: 'confirmed', verified_label: '', image_quality: 'good', next_steps: ['monitor_plant'], notes: '' }); const [error, setError] = useState(''); const [message, setMessage] = useState('');
  const load = useCallback(async () => { try { const [cases, diseases] = await Promise.all([api(`/expert/diagnosis-reviews?scope=${reviewed ? 'reviewed' : 'pending'}`), api('/expert/diseases')]); setItems(cases.data.map(mapDiagnosis)); setClasses(diseases.data.map((item) => item.model_class_key).filter(Boolean)); const requested = new URLSearchParams(window.location.search).get('case'); if (requested) setSelected(cases.data.map(mapDiagnosis).find((item) => item.id === requested) || null); } catch (exception) { setError(exception.message); } }, [reviewed]); useEffect(() => { load(); }, [load]);
  const submit = async (event) => { event.preventDefault(); try { const payload = await api(`/expert/diagnosis-reviews/${selected.id}`, { method: 'PUT', body: JSON.stringify({ ...form, verified_label: form.review_status === 'alternate_class' ? form.verified_label : null }) }); setSelected(mapDiagnosis(payload.data)); setMessage('Review saved. The original AI prediction remains unchanged.'); setError(''); load(); } catch (exception) { setError(exception.message); } };
  const nominate = async () => { try { await api(`/expert/dataset-candidates/from-diagnosis/${selected.id}`, { method: 'POST' }); setMessage('Image nominated for manual dataset review. It was not added to training data.'); } catch (exception) { setError(exception.message); } };
  return <div className="role-stack"><Heading eyebrow="AGRICULTURAL REVIEWER" title={reviewed ? 'Reviewed Cases' : 'Case Reviews'} text={reviewed ? 'Audit completed assessments alongside the preserved AI result.' : 'Review farmer requests and uncertain model results using only supported classes.'} />{error && <div className="form-error">{error}</div>}{message && <div className="success-message">{message}</div>}<section className="expert-review-layout"><div className="panel expert-case-list">{items.map((item) => <button key={item.id} className={`expert-case-row ${selected?.id === item.id ? 'active' : ''}`} onClick={() => { setSelected(item); setMessage(''); setForm({ review_status: item.review?.review_status === 'pending' ? 'confirmed' : item.review?.review_status || 'confirmed', verified_label: item.review?.verified_label || '', image_quality: item.review?.image_quality || 'good', next_steps: item.review?.next_steps || ['monitor_plant'], notes: item.review?.notes || '' }); }}>{item.image ? <img src={item.image} alt="Leaf submitted for review" /> : <span><Leaf size={23} /></span>}<div><strong>{item.disease?.name || titleCase(item.predictedClass)}</strong><small>{item.user?.name || 'Unknown farmer'} · {formatDate(item.date)}</small>{!reviewed && <small className="priority-reason">{item.reviewReasons.join(' · ')}</small>}</div><b>{reviewed ? `${item.confidence.toFixed(1)}%` : `P${Math.round(item.priority)}`}</b><ChevronRight size={18} /></button>)}{!items.length && <Empty icon={Check} title={reviewed ? 'No completed reviews yet.' : 'No cases need review.'} text={reviewed ? 'Completed assessments will appear here.' : 'New farmer requests and uncertain results will appear here.'} />}</div>{selected && <article className="panel expert-review-card"><span className="section-label">ORIGINAL MODEL OUTPUT — READ ONLY</span>{selected.image ? <img className="expert-leaf-image" src={selected.image} alt="Original submitted banana leaf" /> : <div className="expert-leaf-placeholder"><Leaf size={42} /></div>}<dl><div><dt>AI prediction</dt><dd>{titleCase(selected.predictedClass)}</dd></div><div><dt>Model confidence</dt><dd>{selected.confidence.toFixed(1)}%</dd></div><div><dt>Farmer</dt><dd>{selected.user?.name || 'Unknown'}</dd></div><div><dt>Date</dt><dd>{formatDate(selected.date, true)}</dd></div>{selected.farmerNotes && <div><dt>Farmer notes</dt><dd>{selected.farmerNotes}</dd></div>}</dl>{selected.gradcam && <details><summary>Areas the system noticed</summary><img className="expert-gradcam" src={selected.gradcam} alt="Model attention visualization" /></details>}{reviewed ? <section className="review-result"><span className="section-label">AGRICULTURAL REVIEWER ASSESSMENT</span><h3>{titleCase(selected.review?.review_status?.replaceAll('_', '-') || '')}</h3>{selected.review?.verified_label && <p><strong>Supported class:</strong> {titleCase(selected.review.verified_label)}</p>}<p><strong>Image quality:</strong> {titleCase(selected.review?.image_quality?.replaceAll('_', '-') || 'Not recorded')}</p><p><strong>Next steps:</strong> {selected.review?.next_steps?.map((step) => titleCase(step.replaceAll('_', '-'))).join(' · ') || 'None recorded'}</p><p>{selected.review?.notes || 'No notes provided.'}</p>{selected.image && <button className="secondary-button full" onClick={nominate}><Database size={17} />Nominate as Dataset Candidate</button>}</section> : <form className="expert-review-form" onSubmit={submit}><h2>Agricultural Review</h2><fieldset><legend>Does the image support the AI result?</legend>{[['confirmed','Confirm AI prediction'],['alternate_class','Select another supported class'],['cannot_determine','Cannot determine from image'],['field_or_laboratory_required','Requires field/laboratory examination'],['possible_outside_supported_classes','Possible condition outside supported classes']].map(([value,label]) => <label key={value}><input type="radio" name="review_status" value={value} checked={form.review_status === value} onChange={(event) => setForm({ ...form, review_status: event.target.value })} />{label}</label>)}</fieldset><fieldset><legend>Image quality</legend>{[['good','Good'],['blurry','Blurry'],['poor_lighting','Poor lighting'],['disease_area_not_visible','Disease area not visible'],['insufficient_image','Insufficient image']].map(([value,label]) => <label key={value}><input type="radio" name="image_quality" value={value} checked={form.image_quality === value} onChange={(event) => setForm({ ...form, image_quality: event.target.value })} />{label}</label>)}</fieldset><fieldset><legend>Recommended next step</legend>{[['retake_photo','Retake photo'],['monitor_plant','Monitor plant'],['isolate_affected_plant','Isolate affected plant'],['seek_field_inspection','Seek field inspection'],['other','Other']].map(([value,label]) => <label key={value}><input type="checkbox" checked={form.next_steps.includes(value)} onChange={(event) => setForm({ ...form, next_steps: event.target.checked ? [...form.next_steps, value] : form.next_steps.filter((item) => item !== value) })} />{label}</label>)}</fieldset>{form.review_status === 'alternate_class' && <label>Supported class<select required value={form.verified_label} onChange={(event) => setForm({ ...form, verified_label: event.target.value })}><option value="">Select class</option>{classes.map((value) => <option key={value}>{value}</option>)}</select></label>}<label>Professional notes<textarea value={form.notes} onChange={(event) => setForm({ ...form, notes: event.target.value })} placeholder="State what the image supports and its limitations." /></label><button className="primary-button">Submit Review</button></form>}</article>}</section></div>;
}

function ExpertDiseases() {
  const [items, setItems] = useState([]); const [detail, setDetail] = useState(null); const [notes, setNotes] = useState(''); const [error, setError] = useState(''); const [message, setMessage] = useState('');
  const load = useCallback(() => api('/expert/diseases').then((payload) => setItems(payload.data)).catch((exception) => setError(exception.message)), []); useEffect(() => { load(); }, [load]);
  const inspect = async (item) => { try { const payload = await api(`/expert/diseases/${item.id}`); setDetail(payload.data); setNotes(''); setError(''); } catch (exception) { setError(exception.message); } }; const decide = async (status) => { try { await api(`/expert/diseases/${detail.disease.id}/verification`, { method: 'POST', body: JSON.stringify({ status, notes }) }); setMessage(`Review recorded: ${titleCase(status.replaceAll('_', '-'))}.`); setDetail(null); setNotes(''); load(); } catch (exception) { setError(exception.message); } };
  return <div className="role-stack"><Heading eyebrow="AGRICULTURAL REVIEWER" title="Disease Knowledge" text="Verify researched agricultural content and return incomplete records for revision." />{error && <div className="form-error">{error}</div>}{message && <div className="success-message">{message}</div>}<section className="panel admin-table-role knowledge-table"><header><span>Disease</span><span>Pathogen</span><span>Status</span><span>Evidence</span><span>Sources</span><span>Last reviewed</span><span>Actions</span></header>{items.map((item) => <div key={item.id}><span><strong>{item.name}</strong><small>{item.model_class_key}</small></span><span>{item.causal_agent || 'Pending'}</span><span><b className={`status-pill ${item.verification_status}`}>{item.verification_status}</b></span><span>{item.evidence_level}</span><span>{item.sources_count ?? 0}</span><span>{formatDate(item.last_reviewed_at)}</span><span><button onClick={() => inspect(item)}>Review</button></span></div>)}</section>{detail && <section className="panel expert-content-review"><header><div><span className="section-label">CONTENT VERIFICATION</span><h2>{detail.disease.name}</h2></div><IconButton label="Close" onClick={() => setDetail(null)}><X size={20} /></IconButton></header><div className="expert-content-grid"><article><h3>Farmer content</h3><p>{detail.disease.description || 'Missing farmer summary.'}</p><h3>Symptoms</h3><p>{detail.disease.symptoms?.join(' · ') || 'No image-visible symptoms documented.'}</p><h3>Management and prevention</h3><p>{detail.disease.management || 'No management content documented.'}</p></article><article><h3>Scientific record</h3><p><strong>Causal agent:</strong> {detail.disease.causal_agent || 'Pending'}</p><p><strong>Evidence level:</strong> {detail.disease.evidence_level}</p><p><strong>Research sources:</strong> {detail.disease.sources_count ?? 0}</p><p><strong>Image limitation:</strong> {detail.disease.image_only_limitations || 'Not documented.'}</p>{detail.regulatory_recheck_required && <div className="form-error">FPA / REGULATORY RE-CHECK REQUIRED</div>}</article></div><label>Reviewer notes<textarea value={notes} onChange={(event) => setNotes(event.target.value)} placeholder="Record evidence gaps, corrections, or verification rationale." /></label><footer><button className="primary-button" disabled={detail.disease.verification_status !== 'researched'} onClick={() => decide('verified')}>Verify Content</button><button className="secondary-button" onClick={() => decide('revision_required')}>Request Revision</button><button className="danger-button" onClick={() => decide('rejected')}>Reject</button></footer></section>}</div>;
}

function ExpertDatasetCandidates() {
  const [items, setItems] = useState([]); const [filter, setFilter] = useState(''); const [notes, setNotes] = useState({}); const [error, setError] = useState(''); const [message, setMessage] = useState('');
  const load = useCallback(() => api(`/expert/dataset-candidates${filter ? `?status=${filter}` : ''}`).then((payload) => setItems(payload.data)).catch((exception) => setError(exception.message)), [filter]); useEffect(() => { load(); }, [load]);
  const decide = async (item, status) => { try { await api(`/expert/dataset-candidates/${item.id}`, { method: 'PUT', body: JSON.stringify({ status, review_notes: notes[item.id] || null }) }); setMessage('Manual dataset-candidate decision recorded.'); setError(''); load(); } catch (exception) { setError(exception.message); } };
  return <div className="role-stack"><Heading eyebrow="RESEARCH ONLY" title="Candidate Dataset Images" text="Reviewed production images remain outside training data until a separate manual approval decision is recorded." /><div className="development-note"><Info size={18} /><p>Approval marks research eligibility only. Export, consent checks, de-identification, and inclusion in a future training dataset remain separate controlled steps.</p></div><section className="panel diagnosis-filters"><label>Status<select value={filter} onChange={(event) => setFilter(event.target.value)}><option value="">All candidates</option>{['pending','approved','rejected','uncertain'].map((value) => <option key={value}>{titleCase(value)}</option>)}</select></label></section>{error && <div className="form-error">{error}</div>}{message && <div className="success-message">{message}</div>}<section className="dataset-candidate-grid">{items.map((item) => <article className="panel dataset-candidate" key={item.id}>{item.diagnosis?.image_url ? <img src={item.diagnosis.image_url} alt="Reviewed candidate banana leaf" /> : <div className="expert-leaf-placeholder"><Leaf size={35} /></div>}<span className={`status-pill ${item.status}`}>{item.status}</span><h2>{item.diagnosis?.disease?.name || titleCase(item.diagnosis?.predicted_class || '')}</h2><p><strong>AI:</strong> {titleCase(item.diagnosis?.predicted_class || '')} · {Number(item.diagnosis?.confidence || 0).toFixed(1)}%</p><p><strong>Agricultural review:</strong> {titleCase(item.diagnosis?.review?.review_status?.replaceAll('_', '-') || 'Pending')}</p><textarea value={notes[item.id] ?? item.review_notes ?? ''} onChange={(event) => setNotes({ ...notes, [item.id]: event.target.value })} placeholder="Record why this image should be approved, rejected, or kept uncertain." /><footer><button className="primary-button" onClick={() => decide(item, 'approved')}>Approve</button><button className="secondary-button" onClick={() => decide(item, 'uncertain')}>Uncertain</button><button className="danger-button" onClick={() => decide(item, 'rejected')}>Reject</button></footer></article>)}{!items.length && <Empty icon={Database} title="No research candidates found." text="A reviewer must first complete a case assessment and manually nominate an image." />}</section></div>;
}

function ExpertSources() {
  const { data, error } = useAdmin('/expert/research-sources'); if (error) return <div className="form-error">{error}</div>; if (!data) return <Loading text="Loading research sources..." />;
  return <div className="role-stack"><Heading eyebrow="AGRICULTURAL REVIEWER" title="Research Sources" text="Review the evidence used for disease claims. Administrators retain source-management access." /><section className="panel admin-table-role source-table"><header><span>Reference</span><span>Year</span><span>Type</span><span>Quality</span><span>Claims</span><span>Link</span></header>{data.map((item) => <div key={item.id}><span><strong>{item.authors} ({item.year || 'n.d.'}). {item.title}.</strong><small>{item.journal_or_institution}</small></span><span>{item.year || 'n.d.'}</span><span>{titleCase(item.source_type.replaceAll('_','-'))}</span><span>{item.peer_reviewed ? 'Peer reviewed' : 'Authoritative'}{item.philippines_specific ? ' · Philippines' : ''}</span><span>{item.evidence_count}</span><span>{item.reference_url ? <a href={item.reference_url} target="_blank" rel="noreferrer">Open source</a> : 'No link'}</span></div>)}</section></div>;
}

function SystemAdmin() {
  const { data, error } = useAdmin('/admin/system'); if (error) return <div className="form-error">{error}</div>; if (!data) return <Loading text="Loading system information..." />; const fields = [['Model', data.model], ['Attention', data.attention], ['Deployment', data.deployment], ['Version', data.version || 'Not configured'], ['Input size', data.input_size || 'Not configured'], ['Classes', data.classes.length ? data.classes.join(', ') : 'Not configured'], ['Confidence threshold', `${data.confidence_threshold}%`]];
  return <div className="role-stack"><Heading eyebrow="ADMIN / RESEARCH" title="System / Model Information" text="Technical deployment details are visible only to administrators." /><section className="panel system-role-card"><div className="system-mode"><span>AI Mode</span><strong>{data.ai_mode}</strong></div><dl>{fields.map(([label, value]) => <div key={label}><dt>{label}</dt><dd>{value}</dd></div>)}</dl><div className="development-note"><Info size={18} /><p>Performance values are omitted until validated research artifacts are available.</p></div></section></div>;
}

function ModelComparisonAdmin() {
  const input = useRef(null); const [file, setFile] = useState(null); const [preview, setPreview] = useState(''); const [result, setResult] = useState(null); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  useEffect(() => () => { if (preview) URL.revokeObjectURL(preview); }, [preview]);
  const choose = (next) => { if (!next?.type.startsWith('image/')) { setError('Choose a JPG, PNG, or WEBP banana-leaf image.'); return; } if (preview) URL.revokeObjectURL(preview); setFile(next); setPreview(URL.createObjectURL(next)); setResult(null); setError(''); };
  const compare = async () => { if (!file) return; setBusy(true); setError(''); setResult(null); const body = new FormData(); body.append('image', file); try { const payload = await api('/admin/model-comparison', { method: 'POST', body }); setResult(payload.data); } catch (exception) { setError(exception.message); } finally { setBusy(false); } };
  const ModelResult = ({ title, value }) => <article className="comparison-model-card"><span>{title}</span><h2>{title === 'Baseline' ? 'MobileNetV3-Small' : 'CA-MobileNetV3-Small'}</h2><dl><div><dt>Prediction</dt><dd>{titleCase(value.predicted_class)}</dd></div><div><dt>Confidence</dt><dd>{(Number(value.confidence) * 100).toFixed(2)}%</dd></div><div><dt>Inference time</dt><dd>{Number(value.inference_time_ms).toFixed(2)} ms</dd></div><div><dt>Model size</dt><dd>{(Number(value.model_size_bytes) / 1048576).toFixed(2)} MB</dd></div></dl></article>;
  return <div className="role-stack"><Heading eyebrow="ADMIN / RESEARCH" title="Model comparison" text="Run the standard baseline and enhanced model on one shared image. Research runs are not saved to farmer history." /><section className="panel comparison-workspace"><div className="comparison-image-panel">{preview ? <img src={preview} alt="Banana leaf selected for model comparison" /> : <div><FileImage size={38} /><strong>Select one banana leaf image</strong><small>JPG, PNG, or WEBP · up to 10 MB</small></div>}<input ref={input} hidden type="file" accept="image/jpeg,image/png,image/webp" onChange={(event) => choose(event.target.files[0])} /></div><div className="comparison-actions"><button className="secondary-button" onClick={() => input.current?.click()}><Upload size={17} />{file ? 'Choose another image' : 'Choose image'}</button><button className="primary-button" disabled={!file || busy} onClick={compare}>{busy ? <RefreshCw className="spin" size={17} /> : <GitCompareArrows size={17} />}{busy ? 'Running sequentially...' : 'Run comparison'}</button></div>{error && <div className="form-error">{error}</div>}<div className="development-note"><Info size={18} /><p>Baseline runs first and is released before the enhanced interpreter loads. A higher confidence on one image does not prove higher accuracy.</p></div></section>{result && <><section className="comparison-results"><ModelResult title="Baseline" value={result.baseline} /><ModelResult title="Enhanced" value={result.enhanced} /></section><section className="panel comparison-summary"><span>Comparison summary</span><h2>{result.comparison.summary}</h2><dl><div><dt>Prediction agreement</dt><dd>{result.comparison.prediction_agreement ? 'Agreement' : 'Different predictions'}</dd></div><div><dt>Enhanced confidence difference</dt><dd>{Number(result.comparison.enhanced_confidence_difference_percentage_points) >= 0 ? '+' : ''}{Number(result.comparison.enhanced_confidence_difference_percentage_points).toFixed(2)} points</dd></div><div><dt>Enhanced latency difference</dt><dd>{Number(result.comparison.enhanced_latency_difference_ms) >= 0 ? '+' : ''}{Number(result.comparison.enhanced_latency_difference_ms).toFixed(2)} ms</dd></div></dl><p>{result.comparison.interpretation_note}</p></section></>}</div>;
}

export default function RoleApp() {
  const first = window.location.pathname; const [path, setPath] = useState(first === '/' ? '/login' : first); const [user, setUser] = useState(null); const [loading, setLoading] = useState(Boolean(getToken())); const [online, setOnline] = useState(navigator.onLine); const [records, setRecords] = useState([]); const [selected, setSelected] = useState(null);
  const navigate = useCallback((next, replace = false) => { window.history[replace ? 'replaceState' : 'pushState']({}, '', next); setPath(next); }, []);
  useEffect(() => { const pop = () => setPath(window.location.pathname); const network = () => setOnline(navigator.onLine); window.addEventListener('popstate', pop); window.addEventListener('online', network); window.addEventListener('offline', network); return () => { window.removeEventListener('popstate', pop); window.removeEventListener('online', network); window.removeEventListener('offline', network); }; }, []);
  useEffect(() => { if (!getToken()) { setLoading(false); return; } api('/auth/me').then((payload) => setUser(payload.data.user)).catch(() => setToken(null)).finally(() => setLoading(false)); }, []);
  const loadRecords = useCallback(() => { if (user?.role !== 'farmer') return; api('/diagnoses?per_page=100').then((payload) => setRecords(payload.data.items.map(mapDiagnosis))).catch(() => setRecords([])); }, [user]); useEffect(loadRecords, [loadRecords]);
  useEffect(() => { if (!loading && !user && !['/login', '/signup'].includes(path)) navigate('/login', true); }, [loading, user, path, navigate]);
  useEffect(() => { if (!user) return; const legacy = ['/', '/dashboard', '/diagnose', '/history', '/profile'].includes(path); const prefix = user.role === 'admin' ? '/admin' : user.role === 'agricultural_expert' ? '/expert' : '/farmer'; const wrong = !path.startsWith(prefix); if (legacy || wrong) navigate(roleHome(user.role), true); }, [user, path, navigate]);
  const signedOut = () => { setUser(null); setRecords([]); navigate('/login', true); }; const save = async (record, imageFile, requestReview = false) => { const body = new FormData(); body.append('predicted_class', record.diseaseId); body.append('confidence', String(record.confidence)); body.append('inference_time_ms', String(record.latency)); body.append('model_version', record.model || 'simulated-web-adapter'); body.append('source', 'web'); body.append('diagnosed_at', record.date); if (record.farmerNotes) body.append('farmer_notes', record.farmerNotes); if (imageFile) body.append('image', imageFile); let payload = await api('/diagnoses', { method: 'POST', body }); if (requestReview) payload = await api(`/diagnoses/${payload.data.id}/review-request`, { method: 'POST', body: JSON.stringify({ farmer_notes: record.farmerNotes || null }) }); const mapped = mapDiagnosis(payload.data); setRecords((current) => [mapped, ...current]); return mapped; };
  if (loading) return <Loading text="Restoring your secure session..." />; if (!user) return <AuthPage mode={path === '/signup' ? 'register' : 'login'} onAuthenticated={setUser} navigate={navigate} />;
  if (user.role === 'farmer') { const requestReview = async (record, farmerNotes = '') => { const payload = await api(`/diagnoses/${record.id}/review-request`, { method: 'POST', body: JSON.stringify({ farmer_notes: farmerNotes || null }) }); const updated = mapDiagnosis(payload.data); setRecords((current) => current.map((item) => item.id === updated.id ? updated : item)); setSelected(updated); }; let page = <FarmerHome user={user} records={records} online={online} navigate={navigate} onOpen={setSelected} />; if (path === '/farmer/scan') page = <FarmerScan onSaved={save} navigate={navigate} online={online} />; if (path === '/farmer/history') page = <FarmerHistory records={records} navigate={navigate} onOpen={setSelected} />; if (path === '/farmer/diseases') page = <DiseaseGuide />; if (path === '/farmer/profile') page = <ProfilePage user={user} onUser={setUser} onSignedOut={signedOut} />; return <Shell role="farmer" user={user} path={path} navigate={navigate} onSignedOut={signedOut} online={online}>{page}<DiagnosisDialog record={selected} onClose={() => setSelected(null)} onRequestReview={requestReview} /></Shell>; }
  if (user.role === 'agricultural_expert') { let page = <ExpertDashboard navigate={navigate} />; if (path.startsWith('/expert/cases')) page = <ExpertCases />; if (path === '/expert/diseases') page = <ExpertDiseases />; if (path === '/expert/sources') page = <ExpertSources />; if (path === '/expert/dataset') page = <ExpertDatasetCandidates />; if (path === '/expert/reviewed') page = <ExpertCases reviewed />; if (path === '/expert/profile') page = <ProfilePage user={user} onUser={setUser} onSignedOut={signedOut} />; return <Shell role="agricultural_expert" user={user} path={path.split('?')[0]} navigate={navigate} onSignedOut={signedOut} online={online}>{page}</Shell>; }
  let page = <AdminDashboard />; if (path === '/admin/farmers') page = <FarmersAdmin />; if (path === '/admin/experts') page = <ExpertsAdmin />; if (path === '/admin/diagnoses') page = <DiagnosesAdmin />; if (path === '/admin/diseases') page = <DiseasesAdmin />; if (path === '/admin/sources') page = <><ResearchSourcesAdmin /><EvidenceAudit /></>; if (path === '/admin/analytics') page = <AdminAnalytics />; if (path === '/admin/model-comparison') page = <ModelComparisonAdmin />; if (path === '/admin/system') page = <SystemAdmin />; if (path === '/admin/profile') page = <ProfilePage user={user} onUser={setUser} onSignedOut={signedOut} />; return <Shell role="admin" user={user} path={path} navigate={navigate} onSignedOut={signedOut} online={online}>{page}</Shell>;
}
